WITH lines AS (SELECT id, service, host, log_ts, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) li AS attr_key, attr_value), flattened_attrs AS (SELECT id, service, host, log_ts, status_code, attr_key, attr_value, SHIFTRIGHT(status_code, 2) AS status_code_high, CAST((status_code & 8) != 0 AS INT) AS is_flagged FROM lines WHERE host = 'h3'), with_windows AS (SELECT id, service, host, log_ts, status_code, attr_key, attr_value, status_code_high, is_flagged, SUM(status_code_high) OVER (ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) AS status_code_high_sum_2h, LEAD(status_code_high, 2) OVER w_part AS next_status_code_high FROM flattened_attrs WINDOW w_part AS (PARTITION BY attr_key ORDER BY status_code_high, id, attr_key)) SELECT *, LAG(next_status_code_high, 1, 0) OVER w_hist AS prev_next_status_code_high, SUM(status_code_high_sum_2h) OVER (PARTITION BY service, attr_key ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) AS status_code_high_sum_2h_sum_15m, NTILE(4) OVER (ORDER BY next_status_code_high DESC, id, attr_key) AS next_status_code_high_bucket FROM with_windows WINDOW w_hist AS (PARTITION BY host ORDER BY next_status_code_high, id, attr_key)
